import webview
import json
import sys
import gzip
import base64
import tempfile
import os
from pathlib import Path

# HTML이 내장된 버전 - app.html 파일 없이 동작
_HTML_DATA = ""

def get_html_path():
    """내장된 HTML을 임시 파일로 추출"""
    html_bytes = gzip.decompress(base64.b64decode(_HTML_DATA))
    tmp = tempfile.NamedTemporaryFile(
        mode='wb', suffix='.html', delete=False,
        prefix='budget_'
    )
    tmp.write(html_bytes)
    tmp.close()
    return tmp.name

if getattr(sys, 'frozen', False):
    DATA_DIR = Path(sys.executable).parent
else:
    DATA_DIR = Path(__file__).parent

DATA_FILE = DATA_DIR / 'budget_data.json'


def load_data():
    if DATA_FILE.exists():
        with open(DATA_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
            if 'customCats' not in data: data['customCats'] = []
            if 'assetData' not in data: data['assetData'] = {'accounts':[],'debts':[],'investments':[]}
            if 'fixed' not in data: data['fixed'] = []
            if 'includeDebtInNet' not in data: data['includeDebtInNet'] = False
            return data
    return {
        'transactions': [],
        'fixed': [],
        'customCats': [],
        'assetData': {'accounts':[],'debts':[],'investments':[]},
        'includeDebtInNet': False
    }


def save_data(data):
    with open(DATA_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


class Api:
    def get_data(self):
        return load_data()

    def save_transactions(self, transactions):
        data = load_data()
        data['transactions'] = transactions
        save_data(data)
        return {'ok': True}

    def save_fixed(self, fixed):
        data = load_data()
        data['fixed'] = fixed
        save_data(data)
        return {'ok': True}

    def save_custom(self, customCats, assetData, includeDebtInNet=False):
        data = load_data()
        data['customCats'] = customCats
        data['assetData'] = assetData
        data['includeDebtInNet'] = includeDebtInNet
        save_data(data)
        return {'ok': True}

    def open_url(self, url):
        import webbrowser
        webbrowser.open(url)
        return {'ok': True}

    def clear_all(self):
        save_data({
            'transactions': [],
            'fixed': [],
            'customCats': [],
            'assetData': {'accounts':[],'debts':[],'investments':[]},
            'includeDebtInNet': False
        })
        return {'ok': True}


if __name__ == '__main__':
    api = Api()
    html_path = get_html_path()

    try:
        window = webview.create_window(
            title='내 가계부 v1.1.0',
            url=html_path,
            js_api=api,
            width=1280,
            height=820,
            min_size=(960, 640),
            background_color='#0f0f0f'
        )
        webview.start(debug=False)
    finally:
        # 임시 파일 삭제
        try:
            os.unlink(html_path)
        except:
            pass
